// Keep every candidate inside the same center space and banner footprint.
const banners = [...document.querySelectorAll('gold-rush-headline')];
function fitNumbers() {
  for (const banner of banners) {
    const amount = banner.querySelector('.gr__amount');
    amount.style.removeProperty('font-size');
    const unit = banner.querySelector('.gr__unit-code');
    const unitLabel = innerWidth >= 1100 ? 'ETHEREUM' : 'ETH';
    if (unit && unit.textContent !== unitLabel) unit.textContent = unitLabel;
    if (innerWidth < 1100) continue;
    const row = banner.querySelector('.gr__amount-row');
    const available = banner.clientWidth * .44;
    const size = parseFloat(getComputedStyle(amount).fontSize);
    // Rects come back zoomed when the desktop board is scaled; work in layout px.
    const zoom = banner.currentCSSZoom || parseFloat(getComputedStyle(banner).zoom) || 1;
    const width = node => node.getBoundingClientRect().width / zoom;
    const extra = width(row) - width(amount);
    if (width(row) > available) {
      amount.style.fontSize = `${size * Math.max(.1, (available - extra) / width(amount))}px`;
    }
    if (banner.dataset.bannerStyle === 'original') {
      const bounds = banner.getBoundingClientRect();
      // Use actual pixels for both axes so the clipped corners and gold outline
      // agree even when the banner is much wider than the original SVG.
      const width = banner.offsetWidth, height = banner.offsetHeight;
      const corner = parseFloat(getComputedStyle(banner).getPropertyValue('--gr-corner')) || height * .0825;
      const c = corner + .25, right = width - .5, bottom = height - .5;
      const path = `M${c} .5H${width-c}L${right} ${c}V${height-c}L${width-c} ${bottom}H${c}L.5 ${height-c}V${c}Z`;
      const outline = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><path d="${path}" fill="none" stroke="#c9a645" stroke-width="1"/></svg>`;
      banner.style.setProperty('--hub-banner-outline', `url("data:image/svg+xml,${encodeURIComponent(outline)}")`);

      const digits = amount.getBoundingClientRect();
      const wing = getComputedStyle(banner.querySelector('.gr__inner'), '::before');
      // The intact chip artwork is 390 × 400 and uses background-size: contain.
      const chipWidth = Math.min(parseFloat(wing.width), parseFloat(wing.height) * 390 / 400);
      const chipEdge = parseFloat(wing.left) + chipWidth;
      const digitLeft = (digits.left - bounds.left) / zoom, digitRight = (digits.right - bounds.left) / zoom;
      banner.style.setProperty('--caption-left-center', `${(chipEdge + digitLeft) / 2}px`);
      banner.style.setProperty('--caption-right-center', `${(width - chipEdge + digitRight) / 2}px`);
    }
  }
}
const picker = document.querySelector('#number-font');
picker?.addEventListener('change', async () => {
  banners[0].dataset.numberFont = picker.value;
  fitNumbers();
  await document.fonts.ready;
  fitNumbers();
});
const observer = new ResizeObserver(fitNumbers);
banners.forEach(banner => {
  observer.observe(banner);
  new MutationObserver(fitNumbers).observe(banner,{childList:true,subtree:true,characterData:true});
});
document.fonts.ready.then(fitNumbers);
document.fonts.addEventListener('loadingdone', fitNumbers);

document.querySelector('#banner-style')?.addEventListener('change', fitNumbers);
